package ir.orix.school.assessment.persistence;
import java.math.BigDecimal; import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import ir.orix.school.assessment.domain.AssessmentQuestion;
public interface AssessmentQuestionRepository extends JpaRepository<AssessmentQuestion, Long>{ @EntityGraph(attributePaths={"section","questionVersion","questionVersion.question"}) List<AssessmentQuestion> findAllByAssessmentIdOrderBySectionSequenceNumberAscSequenceNumberAsc(Long assessmentId); boolean existsByAssessmentIdAndQuestionVersionId(Long assessmentId,Long versionId); boolean existsBySectionIdAndSequenceNumber(Long sectionId,int sequence); @Query("select coalesce(sum(q.points),0) from AssessmentQuestion q where q.assessment.id=:assessmentId") BigDecimal totalPoints(@Param("assessmentId") Long assessmentId); }
